mapper.update:
BEGIN
    EXECUTE IMMEDIATE 'ALTER TABLE ACCOMMODATION DROP CONSTRAINT CHK_ACCOM_TYPE';
EXCEPTION
    WHEN OTHERS THEN NULL;
END;

mapper.select:
SELECT COUNT(*)
FROM ACCOMMODATION
WHERE TOUR_API_ID = #{tourApiId}

SELECT * FROM (
    SELECT
        a.*,
        ROW_NUMBER() OVER (ORDER BY CREATED_AT DESC) AS rn
    FROM ACCOMMODATION a
    WHERE STATUS = 'A'

        AND REGION = #{region}

)
WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.insert:
INSERT INTO ACCOMMODATION_IMAGE (
    IMAGE_NO, ACCOMMODATION_NO, IMAGE_URL, IMAGE_ORDER, CREATED_AT
) VALUES (
    SEQ_ACCOM_IMG_NO.NEXTVAL, #{accommodationNo}, #{imageUrl}, #{imageOrder}, SYSDATE
)
